// sweep: a 4 x 6 rectangle along a line and a fit spline leaving it tangentially, twisted a quarter turn
export function c006(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skRectangle(profile, "rect1", { "firstCorner" : vector(-2, -3) * millimeter, "secondCorner" : vector(2, 3) * millimeter });
    skSolve(profile);
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(path, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skFitSpline(path, "spline1", { "points" : [vector(10, 0) * millimeter, vector(25, 5) * millimeter, vector(40, 0) * millimeter], "startDerivative" : vector(15, 0) * millimeter });
    skSolve(path);
    sweep(context, id + "sweep1", { "profiles" : qSketchRegion(id + "profile"), "path" : qOwnedByBody(qBodyType(qCreatedBy(id + "path", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "hasTwist" : true, "twistType" : SweepTwistType.ANGLE, "angle" : 90 * degree, "ccw" : true });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "sweep1", EntityType.BODY), BodyType.SOLID)) };
}

// offset-curve-on-face: a hemisphere's equator offset 3 mm up its sphere
export function c007(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(profile, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skArc(profile, "a1", { "start" : vector(10, 0) * millimeter, "mid" : vector(7.071068, 7.071068) * millimeter, "end" : vector(0, 10) * millimeter });
    skLineSegment(profile, "l2", { "start" : vector(0, 10) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(profile);
    const axisSketch = newSketchOnPlane(context, id + "axisSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(0, 0, 1)) });
    skLineSegment(axisSketch, "l1", { "start" : vector(-50, 0) * millimeter, "end" : vector(50, 0) * millimeter });
    skSolve(axisSketch);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "profile"), "axis" : qCreatedBy(id + "axisSketch", EntityType.EDGE), "fullRevolve" : true });
    offsetCurveOnFace(context, id + "offset1", { "edges" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(10, 0, 0) * millimeter), "distance" : 3 * millimeter, "offsetType" : OffsetCurveType.GEODESIC, "oppositeDirection" : false, "gapFill" : GapFill.LINEAR, "scope" : OffsetCurveScope.OFFSET, "targets" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.SPHERE) });
    return { "edges" : edgeProbe(context, qCreatedBy(id + "offset1", EntityType.BODY)) };
}

// body-draft: a block drafted 3 degrees on both sides of a cylindrical sheet through it, not matching at the sheet
export function c008(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 12 * millimeter });
    const pull = newSketchOnPlane(context, id + "pull", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(pull, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(pull);
    const arcSketch = newSketchOnPlane(context, id + "arcSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(arcSketch, "arc1", { "start" : vector(-5, 6) * millimeter, "mid" : vector(20, 9) * millimeter, "end" : vector(45, 6) * millimeter });
    skSolve(arcSketch);
    extrude(context, id + "part", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "arcSketch", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 40 * millimeter, "oppositeDirection" : true });
    bodyDraft(context, id + "draft1", { "selectionType" : BodyDraftSelectionType.PARTS, "bodies" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "excludeFaces" : qNothing(), "draftOnSelf" : false, "pullDirection" : qCreatedBy(id + "pull", EntityType.EDGE), "flipPullDirection" : false, "partingObject" : qOwnedByBody(qBodyType(qCreatedBy(id + "part", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "angle" : 3 * degree, "bothSides" : true, "matchFacesAtParting" : false, "cornerType" : BodyDraftCornerType.EXTEND, "keepMaterial" : false });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}

